#' @title plot.PCoA.biplot
#'
#' @description Plot a biplot of the principal coordinates from an object generated by \link{perform.PCoA}.
#' The sample scores (dots) are overlaid with the projection of the proteins (arrows) onto the selected
#' 2D plane of the ordination.
#'
#' @param DEprot.PCoA.object An object of class \code{DEprot.PCoA}, as generated by \link{perform.PCoA} \strong{providing a \code{DEprot.object}} (the \code{axis.loadings} slot must not be empty).
#' @param PCo.x Number indicating which Principal Coordinate (PCo) to display on the x-axis. Default: \code{2} (PCo2).
#' @param PCo.y Number indicating which Principal Coordinate (PCo) to display on the y-axis. Default: \code{1} (PCo1).
#' @param color.column String indicating the name of the column in the \code{metadata} to use as factor for the dot colors. Default: \code{"column.id"} (each sample a color).
#' @param shape.column String indicating the name of the column in the \code{metadata} to use as factor for the dot shapes. Default: \code{NULL} (all dots).
#' @param label.column String indicating the name of the column in the \code{metadata} to use as label of the dots. Default: \code{NULL} (no labeling).
#' @param plot.zero.line.x Logical value to indicate whether to plot a gray dashed line in correspondence of x=0. Default: \code{TRUE}.
#' @param plot.zero.line.y Logical value to indicate whether to plot a gray dashed line in correspondence of y=0. Default: \code{TRUE}.
#' @param n.loadings Integer indicating the number of top contributing protein projections (arrows) to display. Proteins are ranked by their Euclidean distance from the origin in the selected 2D plane. Default: \code{10}.
#' @param min.abs.correlation Numeric value (0 to 1) indicating the minimum absolute correlation with at least one of the two axes required for a protein to be displayable. Default: \code{0} (no filtering).
#' @param loading.color String indicating the color used for the arrows and labels. Default: \code{"darkorange3"}.
#' @param loading.arrow.size Numeric value indicating the linewidth of the arrows. Default: \code{0.6}.
#' @param loading.label.size Numeric value indicating the font size of the labels. Default: \code{3}.
#' @param loading.alpha Numeric value (0 to 1) indicating the transparency of arrows and labels. Default: \code{0.7}.
#' @param loading.scale Numeric value used as a multiplier to manually adjust the scaling of the arrows relative to the sample scores. Values > 1 make arrows longer, values < 1 make them shorter. Default: \code{0.8}.
#'
#' @return A ggplot object.
#'
#' @details
#' \strong{These arrows are NOT PCA loadings.} A PCoA is computed on the sample-by-sample dissimilarity matrix
#' and therefore has no native protein loadings: nothing was rotated, and the proteins never entered the
#' ordination. The arrows displayed here are the a-posteriori correlation between each protein profile and each
#' principal coordinate (stored in the \code{axis.loadings} slot by \link{perform.PCoA}), i.e. the direction along
#' which each protein increases in the ordination space. They are an interpretative aid and must not be read as
#' the rotation coefficients returned by \link{plot.PC.biplot}.\cr\cr
#' Because the projections are correlations computed over the samples only, they are noisy when few samples are
#' available: with a typical proteomics design (6-12 samples) a protein carrying no signal can correlate strongly
#' with an axis by chance. The \code{min.abs.correlation} argument allows a minimal filtering, but the ranking
#' should always be treated as exploratory and validated with the differential analyses.\cr\cr
#' The arrow length is bounded by construction (correlations lie between -1 and 1), so it reflects how well a
#' protein aligns with the plane, not the magnitude of its intensity change.
#'
#' @seealso \link{perform.PCoA}, \link{plot.PCoA.scatter}, \link{plot.PC.biplot}
#'
#' @name plot.PCoA.biplot
#'
#' @import ggplot2
#' @importFrom stringr str_to_title
#' @import ggrepel
#'
#' @author Sebastian Gregoricchio
#'
#' @examples
#' # Compute the sample correlations
#' correlation <- plot.correlation.heatmap(DEprot.object = DEprot::test.toolbox$dpo.imp,
#'                                         correlation.method = "spearman")
#'
#' # The DEprot.object must be provided to compute the protein projections
#' pcoa <- perform.PCoA(DEprot.correlation.object = correlation,
#'                      DEprot.object = DEprot::test.toolbox$dpo.imp)
#'
#' # Plot the biplot of PCo1-vs-PCo2
#' plot.PCoA.biplot(DEprot.PCoA.object = pcoa,
#'                  PCo.x = 1,
#'                  PCo.y = 2,
#'                  color.column = "condition",
#'                  n.loadings = 10)
#'
#' @export plot.PCoA.biplot

plot.PCoA.biplot =
  function(DEprot.PCoA.object,
           PCo.x = 2,
           PCo.y = 1,
           color.column = "column.id",
           shape.column = NULL,
           label.column = NULL,
           plot.zero.line.x = TRUE,
           plot.zero.line.y = TRUE,
           n.loadings = 10,
           min.abs.correlation = 0,
           loading.color = "darkorange3",
           loading.arrow.size = 0.6,
           loading.label.size = 3,
           loading.alpha = 0.7,
           loading.scale = 0.8) {


    ### check object
    if (!("DEprot.PCoA" %in% class(DEprot.PCoA.object))) {
      stop("The input must be an object of class 'DEprot.PCoA'.")
    }

    ### harmonized access to the ordination slots
    ord = .ordination.slots(DEprot.PCoA.object)


    ### -----------------------------------------------
    ### Extract the protein projections
    ### -----------------------------------------------
    loadings.mat = DEprot.PCoA.object@axis.loadings

    if (is.null(loadings.mat)) {
      stop(paste0("The 'axis.loadings' slot is empty: the protein projections are not available.\n",
                  "       Re-run 'perform.PCoA' providing the 'DEprot.object' used to compute the correlations."))
    }

    pco.x.col = paste0("PCo", PCo.x)
    pco.y.col = paste0("PCo", PCo.y)

    if (!(pco.x.col %in% colnames(loadings.mat)) | !(pco.y.col %in% colnames(loadings.mat))) {
      stop(paste0("The requested axes (", pco.x.col, ", ", pco.y.col,
                  ") are not available in the projections table.\n",
                  "       Available axes: ",
                  paste0(grep("^PCo[0-9]+$", colnames(loadings.mat), value = TRUE), collapse = ", ")))
    }


    ### Build loadings data.frame
    loadings.df = data.frame(variable = loadings.mat$protein,
                             loading.x = loadings.mat[, pco.x.col],
                             loading.y = loadings.mat[, pco.y.col])

    ## remove the proteins for which the projection could not be computed
    loadings.df = loadings.df[!is.na(loadings.df$loading.x) & !is.na(loadings.df$loading.y), , drop = FALSE]


    ### Optional filtering on the strength of the projection
    if (min.abs.correlation > 0) {
      keep = pmax(abs(loadings.df$loading.x), abs(loadings.df$loading.y)) >= min.abs.correlation
      loadings.df = loadings.df[keep, , drop = FALSE]
    }

    if (nrow(loadings.df) == 0) {
      stop(paste0("No protein passes the 'min.abs.correlation' threshold (", min.abs.correlation, ")."))
    }


    ### Rank and rescale the projections (shared with plot.PC.biplot)
    scaled = .scale.loadings(loadings.df = loadings.df,
                             scores.x = ord$coordinates[,pco.x.col],
                             scores.y = ord$coordinates[,pco.y.col],
                             n.loadings = n.loadings,
                             loading.scale = loading.scale)


    ### -----------------------------------------------
    ### Build the biplot (arrows are inserted below the points)
    ### -----------------------------------------------
    biplot =
      .ordination.scatter(coordinates = ord$coordinates,
                          importance = ord$importance,
                          axis.prefix = ord$axis.prefix,
                          axis.x = PCo.x,
                          axis.y = PCo.y,
                          color.column = color.column,
                          shape.column = shape.column,
                          label.column = label.column,
                          plot.zero.line.x = plot.zero.line.x,
                          plot.zero.line.y = plot.zero.line.y,
                          positive.axis = ord$positive.axis,
                          extra.layers = .loading.layers(loadings.top = scaled$top,
                                                         loading.color = loading.color,
                                                         loading.arrow.size = loading.arrow.size,
                                                         loading.label.size = loading.label.size,
                                                         loading.alpha = loading.alpha))

    return(biplot)
  } # END function
